@Mod.EventBusSubscriber(modid="dragonsofberk", bus=Mod.EventBusSubscriber.Bus.FORGE)
public final class FlightSpeedSyncHandler {
    private FlightSpeedSyncHandler() {
    }

    @SubscribeEvent
    public static void onPlayerLoggedIn(PlayerEvent.PlayerLoggedInEvent event) {
        Player player = event.getEntity();
        if (!(player instanceof ServerPlayer)) {
            return;
